import {sampleVisual} from './specimens.js';
import {mineSceneBody} from './mine-study.js';
import {rockIllustration} from './lesson-materials.js';
let sceneSequence=0;
function wrap(type,phase,title,body){const id='scene-'+(++sceneSequence);return `<div class="story-scene ${type} phase-${phase}"><div class="observation-heading"><span>${title}</span><b>虛擬觀察</b></div><svg viewBox="0 0 640 360" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${title}"><defs><linearGradient id="${id}-wall" x2="0" y2="1"><stop stop-color="#edf1e7"/><stop offset="1" stop-color="#dbe4d6"/></linearGradient><linearGradient id="${id}-metal"><stop stop-color="#53665e"/><stop offset=".3" stop-color="#d7dfd6"/><stop offset=".5" stop-color="#f8fcf4"/><stop offset=".7" stop-color="#87968a"/><stop offset="1" stop-color="#45584f"/></linearGradient><linearGradient id="${id}-fire" x2="0" y2="1"><stop stop-color="#fff3b3"/><stop offset=".45" stop-color="#ee9d4b"/><stop offset="1" stop-color="#bd492c"/></linearGradient><pattern id="${id}-brick" width="42" height="24" patternUnits="userSpaceOnUse"><rect width="42" height="24" fill="#8a6754"/><path d="M0 0H42V24H0ZM21 0V12M0 12H42M8 12V24" fill="none" stroke="#d0ac8b" stroke-opacity=".5"/></pattern><filter id="${id}-glow"><feGaussianBlur stdDeviation="8"/></filter></defs><rect width="640" height="360" rx="8" fill="url(#${id}-wall)"/><path d="M0 300H640V360H0Z" fill="#d0dbcc"/><path d="M0 322H640M320 300L80 360M320 300L560 360" stroke="#9caf9e" opacity=".3"/>${body.replaceAll('$METAL',`url(#${id}-metal)`).replaceAll('$FIRE',`url(#${id}-fire)`).replaceAll('$BRICK',`url(#${id}-brick)`).replaceAll('$GLOW',`url(#${id}-glow)`)}</svg></div>`;}
function label(x,y,text,size=15,colour='#3d5a4a'){return `<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="${colour}">${text}</text>`;}
function specimen(s,oxide,x,y,id,options={}){return sampleVisual(s,oxide,true,id,options).replace('<svg ',`<svg x="${x}" y="${y}" width="250" height="160" `);}
function arrow(x,y,len=70){const head=len<0?10:-10;return `<path d="M${x} ${y}h${len}l${head} -7m${-head} 7l${head} 7" fill="none" stroke="#b66c40" stroke-width="3"/>`;}
const atom=(x,y,t,c='#bc644a')=>`<g><circle cx="${x}" cy="${y}" r="16" fill="${c}" stroke="#fff9" stroke-width="2"/>${label(x,y+5,t,12,'#fff')}</g>`;
export function storyScene(type,state={}){
 const p=state.phase||'before',after=p==='after',heating=p==='heating';
 if(type==='mine')return wrap(type,p,'礦石與鐵片｜先觀察，再找解釋',mineSceneBody(state));
 if(type==='activity'){
 const reverse=state.pair==='CuZn',a=reverse?'Cu':'Zn',b=reverse?'Zn':'Cu',done=after&&!reverse;
 return wrap(type,p,reverse?'交換角色｜銅與氧化鋅':'找回銅｜鋅與氧化銅',`${label(172,54,done?'ZnO：冷卻後白色':a==='Zn'?'Zn：灰色鋅粉':'Cu：紅棕色銅',17)}${label(473,54,done?'Cu：紅棕色金屬':b==='Cu'?'CuO：黑色氧化物':'ZnO：白色氧化物',17)}${specimen(a,done,46,90,'pair-a')}${specimen(b,!done,345,90,'pair-b')}${arrow(281,158,40)}${heating?'<path class="forge-flame" d="M80 280Q101 240 119 212Q121 248 149 244Q157 219 174 208Q217 251 224 282Z" fill="$FIRE"/><path class="forge-flame" d="M378 280Q399 240 417 212Q419 248 447 244Q455 219 472 208Q515 251 522 282Z" fill="$FIRE"/>':''}${label(320,323,after?(reverse?'本例條件下，沒有發生淨奪氧反應':'氧轉移到鋅；黑色 CuO 變成紅棕色 Cu'):'比較兩個代表案例，不用亮度排活性',16)}`);
 }
 if(type==='redox')return wrap(type,p,'同一個氧｜從 CuO 轉移到 Zn',`${label(165,53,after?'ZnO｜鋅得氧，被氧化':'Zn｜等待反應',18)}${label(468,53,after?'Cu｜CuO 失氧，被還原':'CuO｜氧原本在這裡',18)}${specimen('Zn',after,40,77,'redox-a')}${specimen('Cu',!after,345,77,'redox-b')}${arrow(390,266,-140)}${atom(160,263,'Zn','#798d89')}${atom(460,263,'Cu','#bc7b55')}${after?`<g class="oxygen-arrival" style="--from-x:220px;--from-y:0px">${atom(200,263,'O')}</g>`:atom(420,263,'O')}${label(320,327,after?'Zn 是還原劑；自己同時被氧化':'氧原子只換位置，沒有消失',16)}`);
 if(type==='reduction'){
 let atoms='';for(let i=0;i<2;i++)atoms+=atom(after?140+i*40:120+i*40,140,'Fe','#727e75');
 for(let i=0;i<3;i++){atoms+=atom(380+i*60,208,'C','#46574e')+atom(380+i*60,170,'O');atoms+=after?`<g class="oxygen-arrival" style="--from-x:${-275-i*20}px;--from-y:-51px;animation-delay:${i*.15}s">${atom(380+i*60,246,'O')}</g>`:atom(105+i*40,195,'O');}
 return wrap(type,p,'CO 還原氧化鐵｜總反應的原子收支',`${label(150,60,after?'2Fe':'Fe₂O₃',22)}${label(440,60,after?'3CO₂':'3CO',22)}${atoms}${arrow(220,185,70)}${label(320,302,'2 個鐵 · 3 個碳 · 6 個氧，前後不變',16)}${label(320,334,after?'Fe₂O₃ 被還原；CO 被氧化':'球色、大小與路徑皆是追蹤模型',14)}`);
 }
 if(type==='furnace'){
 const hot=after&&state.recipe!=='ore',slag=hot&&state.recipe==='full';
 return wrap(type,p,'現代高爐剖面・教學示意',`<ellipse cx="315" cy="327" rx="125" ry="17" fill="#365b3b22"/><path d="M266 36H357V85L403 234L385 310H233L215 234L266 85Z" fill="$BRICK" stroke="#765c48" stroke-width="4"/><path d="M281 45H342V91L385 233L371 293H247L233 233L281 91Z" fill="#3d4138"/><path d="M279 75H344M272 100H352M260 132H364M247 168H375" stroke="#b28c63" stroke-width="12" stroke-dasharray="15 5" class="${hot?'charge-fall':''}"/>${hot?'<path class="gas-rise" d="M285 260Q258 210 302 178Q326 141 305 105M335 255Q361 213 330 183Q304 148 329 110" stroke="#e6c08a" stroke-width="3" stroke-dasharray="8 8" fill="none"/><path class="forge-flame" d="M246 266Q253 219 275 210Q263 247 296 255Q305 224 320 199Q340 252 372 263Z" fill="$FIRE"/><path d="M246 270H372L367 292H251Z" fill="#f0a957"/>':''}${slag?'<path d="M244 258H375L372 270H246Z" fill="#a28f57"/>':''}<path d="M174 250H236M382 250H435" stroke="#8c9690" stroke-width="15"/><path d="M174 250H236M382 250H435" stroke="${hot?'#edaa62':'#bec4ba'}" stroke-width="7" class="${hot?'air-flow':''}"/>${arrow(128,250,39)}${label(104,223,'熱空氣',15)}${label(105,282,hot?'已鼓入':'本模型無還原',13)}<path d="M349 283L424 319H511" stroke="${hot?'#ec9b42':'#79887b'}" stroke-width="7" fill="none"/><path d="M369 262L448 282H529" stroke="${slag?'#b8a36c':'#79887b'}" stroke-width="6" fill="none"/>${label(511,343,hot?'下層：鐵水':'沒有鐵水',14)}${label(523,268,slag?'上層：熔渣':'雜質待處理',14)}<path d="M380 160H479" stroke="#9da991"/><path d="M243 114H162" stroke="#9da991"/>${label(520,161,hot?'CO 向上還原':'缺乏 CO',15)}${label(113,113,'礦料下降',15)}${label(314,24,'原料由爐頂加入',12)}${label(320,352,'位置、流量、時間皆經簡化',11)}`);
 }
 if(type==='slag')return wrap(type,p,'除雜與分層｜上渣、下鐵',`<path d="M164 92H474L452 294Q320 328 187 294Z" fill="$BRICK" stroke="#88705c" stroke-width="3"/><path d="M182 107H456L438 280Q320 307 202 280Z" fill="#39453b"/><path d="M197 223H443L438 280Q320 306 202 280Z" fill="$FIRE"/>${after?'<path class="slag-layer" d="M191 182H449L443 223H197Z" fill="#bba36d"/><path d="M194 183Q320 197 448 183" stroke="#decc8e" stroke-width="4"/>':'<g fill="#c7b18c"><path d="M243 164l32-14 19 24-36 15Z"/><path d="M328 191l23-19 30 22-37 14Z"/></g>'}${label(320,61,after?'CaO ＋ SiO₂ → 矽酸鹽熔渣':'SiO₂ 等雜質仍待移除',18)}${label(320,after?207:175,after?'熔渣':'雜質',17,after?'#3c493b':'#f1e5c7')}${label(320,263,'鐵水',19,'#714126')}${after?'<path class="slag-stream" d="M449 199H531L558 241" fill="none" stroke="#c2a570" stroke-width="9"/><path d="M439 268H495L526 308" fill="none" stroke="#e9a350" stroke-width="9"/>':''}${label(320,347,'石灰石幫助除雜；CO 才是主要還原劑',15)}`);
 if(type==='steel'){
 const material=state.material||'pig',name={pig:'生鐵｜較高含碳',pure:'低碳鐵｜較軟',steel:'適當鋼材｜成分與製程受控'}[material];
 const shape=after&&material==='pure'?'M140 179Q255 269 440 180L440 197Q260 288 140 196Z':'M140 179H450V197H140Z';
 return wrap(type,p,'材料試片｜相同示意負荷的比較',`${label(320,53,name,20)}<ellipse cx="310" cy="304" rx="200" ry="16" fill="#36563b22"/><path d="M133 202H164V291H120ZM430 202H462L477 291H430Z" fill="$METAL"/><path d="${shape}" fill="$METAL" stroke="#73877a" stroke-width="2"/>${after&&material==='pig'?'<path class="crack" d="M296 176l-9 7 14 5-9 11" stroke="#273c31" stroke-width="5" fill="none"/><path d="M291 200l-8 24 13 10 10-17Z" fill="#77877a"/>':''}<g class="${after?'load-down':''}"><path d="M268 90H335V140H268Z" fill="#9eab9c" stroke="#6e826f"/><path d="M275 97H328" stroke="#e9efdf" stroke-width="3"/><path d="M302 143V165l-8-9m8 9l8-9" stroke="#9e6847" stroke-width="3" fill="none"/></g>${label(320,332,after?{pig:'較硬但較脆，示意出現裂痕',pure:'較容易產生永久變形',steel:'在本例負荷下保持完整；並非永不變形'}[material]:'按下觀察，比較材料如何回應負荷',15)}`);
 }
 return '';
}

